cd /home/sauyon/devel/dotfiles/.drovr/wt/orca-mac-keys; S=/tmp/claude-1000/-home-sauyon-devel-dotfiles/9ba483e0-4eab-46f1-a189-99a5f9fcee3e/scratchpad/rev2-correctness; P=/nix/store/REDACTED
timeout 300 nix eval --json ".#homeConfigurations.$(hostname).config.wayland.windowManager.hyprland.settings" --apply 's: builtins.concatMap (k: map (b: if builtins.isAttrs b && b ? _args then builtins.head b._args else b) s.${k}) (builtins.filter (k: builtins.substring 0 4 k == "bind") (builtins.attrNames s))' 2>/dev/null > $S/chords.json
cat > $S/taken.js <<'EOF'
const kb=require(process.argv[2]+'/keybindings.js');
const MODS = { SUPER: 'Cmd', CTRL: 'Ctrl', CONTROL: 'Ctrl', ALT: 'Alt', SHIFT: 'Shift' };
const KEYS = { return: 'Enter', left: 'ArrowLeft', right: 'ArrowRight', up: 'ArrowUp', down: 'ArrowDown' };
for (const chord of JSON.parse(require('fs').readFileSync(process.argv[3],'utf8'))) {
  const parts = chord.split('+').map((s) => s.trim()); const key = parts.pop();
  if (/^(mouse[:_]|XF86)/.test(key) || chord.startsWith('switch:')) { console.log('SKIP', chord); continue; }
  const mods = parts.map((p) => MODS[p.toUpperCase()]);
  const n = kb.normalizeKeybinding([...mods, KEYS[key] ?? key].join('+'));
  console.log(chord, '=>', n.ok ? n.value : 'ERR '+n.error);
}
EOF
node $S/taken.js $P/lib/shared $S/chords.json

